package vn.svframe.svframelib.script.mechanic.movement;import vn.svframe.svframelib.script.mechanic.RawMechanic;import vn.svframe.svframelib.util.configobject.ConfigObject;public class TeleportMechanic extends RawMechanic{public TeleportMechanic(ConfigObject c){super("teleport"+render(c));}private static String render(ConfigObject c){if(c==null||c.getKeys().isEmpty())return "";StringBuilder b=new StringBuilder("{");boolean first=true;for(String k:c.getKeys()){if(!first)b.append(';');first=false;b.append(k).append('=').append(c.getString(k,""));}return b.append('}').toString();}}